import { useState, useEffect } from 'react';

const KEY_MOODS    = 'spiral_moods';
const KEY_THOUGHTS = 'spiral_thoughts';

export function useMoods() {
  const [moods, setMoods] = useState(() => {
    try { return JSON.parse(localStorage.getItem(KEY_MOODS) || '[]'); }
    catch { return []; }
  });

  const addMood = (score, emoji, label, note) => {
    const entry = { id: Date.now(), score, emoji, label, note, date: new Date().toISOString() };
    const updated = [entry, ...moods];
    localStorage.setItem(KEY_MOODS, JSON.stringify(updated));
    setMoods(updated);
    return entry;
  };

  const todayChecked = moods.some(m => {
    const d = new Date(m.date);
    const today = new Date();
    return d.getDate() === today.getDate() && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
  });

  const streak = (() => {
    const dates = [...new Set(moods.map(m => m.date.slice(0, 10)))].sort().reverse();
    let s = 0, check = new Date();
    for (const d of dates) {
      const checkStr = check.toISOString().slice(0, 10);
      if (d === checkStr) { s++; check.setDate(check.getDate() - 1); }
      else break;
    }
    return s;
  })();

  const avgMood = moods.length
    ? Math.round((moods.slice(0, 14).reduce((a, m) => a + m.score, 0) / Math.min(moods.length, 14)) * 10) / 10
    : 0;

  return { moods: moods.slice(0, 14), addMood, todayChecked, streak, avgMood };
}

export function useThoughts() {
  const [thoughts, setThoughts] = useState(() => {
    try { return JSON.parse(localStorage.getItem(KEY_THOUGHTS) || '[]'); }
    catch { return []; }
  });

  const addThought = (entry) => {
    const updated = [entry, ...thoughts];
    localStorage.setItem(KEY_THOUGHTS, JSON.stringify(updated));
    setThoughts(updated);
    return entry;
  };

  const trapCounts = thoughts.reduce((acc, t) => {
    acc[t.trap_label] = (acc[t.trap_label] || 0) + 1;
    return acc;
  }, {});

  return { thoughts: thoughts.slice(0, 10), addThought, trapCounts };
}
